This vault is exploitable. Find the bug and fix it.

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

contract Vault {
    IERC20 public immutable asset;
    uint256 public totalShares;
    mapping(address => uint256) public shares;

    constructor(address _asset) { asset = IERC20(_asset); }

    function deposit(uint256 amount) external returns (uint256 s) {
        uint256 total = asset.balanceOf(address(this));
        s = total == 0 ? amount : (amount * totalShares) / total;
        shares[msg.sender] += s;
        totalShares += s;
        asset.transferFrom(msg.sender, address(this), amount);
    }

    function withdraw(uint256 s) external returns (uint256 amount) {
        amount = (s * asset.balanceOf(address(this))) / totalShares;
        shares[msg.sender] -= s;
        totalShares -= s;
        asset.transfer(msg.sender, amount);
    }
}

An attacker deposits 1 wei, then transfers tokens directly to the vault to
inflate the share price, and the next depositor mints zero shares and loses
their entire deposit.

Return the FIXED contract. It must:
  - keep the name `Vault` and the same constructor signature `constructor(address _asset)`
  - keep `deposit(uint256) returns (uint256)` and `withdraw(uint256) returns (uint256)`
  - still let ordinary depositors withdraw what they put in
  - give two equal depositors equal shares
  - make the inflation attack unprofitable

Output ONLY the Solidity source file. No explanation, no markdown fences.
It must compile standalone on solc 0.8.28 with no imports.
